import { useCallback, useEffect, useRef, useState } from 'react'
import { AlertTriangle, BookOpen, Check, Clapperboard, Film, LoaderCircle, RefreshCw, Save, Sparkles } from 'lucide-react'

type Reference = { id:string; name:string; category:string; path:string; mime_type:string; size_bytes:number; available:boolean }
type Preset = { name:string; frames:number; fps:number; duration:number; status:string; visual_drift_warning?:boolean }
type JobEvent={id:number;time:string;level:string;message:string}
type Shot = { id:string; scene_title:string; title:string; prompt:string; visual_description:string; reference_image:string|null; reference_ids:string[]; characters:string[]; framing:string; preset:string; seed:number|null; caption:string; dialogue:string; width:number;height:number;fps:number;output_location:string;estimated_seconds:number;transition_after:string;generation_payload:Record<string,unknown>;prompt_reviewed:boolean;reviewed_style_revision:number;status?:string;creative_review?:{decision:'approved'|'rejected';reason:string;created_at:string}|null;creative_review_current?:boolean;job?:{id:string;status:string;progress:number;exit_code?:number|null;settings_match?:boolean;error?:string|null;result_path?:string|null;verification_metadata?:{verified_output?:{width:number;height:number;fps:number;frames:number}}|null;events?:JobEvent[]}|null }
type FilmBatch={id:string;storyboard_id:string;status:string;message?:string;progress:number;total_shots:number;completed_shots:number;failed_shots:number;queued_shots:number;running_shots:number;resource_warnings?:string[];composition_warning?:string;shots:{shot_id:string;position:number;status:string;progress:number;skip_reason:string;job?:Shot['job']&{payload?:{job_label?:string}}|null;title:string;scene_title:string}[]}
type RenderJob={id:string;status:string;progress:number;result_path:string|null;elapsed_seconds:number|null;current:boolean;manifest_revision:number|null;verification_metadata?:{verified_output?:{width:number;height:number;fps:number;frames:number}}|null;error?:string|null}
type Plan = { id:string; project_id:string; title:string; revision:number; story_text:string; style_bible_revision:number; style_bible:Record<string,string>; shots:Shot[];manifest?:{revision:number;width:number;height:number;fps:number;duration_in_frames:number;shots?:unknown[]}|null;manifest_path?:string|null; film_plan?:{approved:boolean;approved_revision:number|null;metadata:{scenes:{title:string;visual_description:string;estimated_seconds:number;transition_after:string}[];shot_count:number;estimated_seconds:number;expected_workload:string;benchmark_estimate:{samples:number;average_seconds_per_shot:number;total_seconds:number;source:string}|null;experimental_drift_warning:boolean;reference_conditioning:string;reference_limit_note:string;planner_disclosure:string;style_bible_notice:string;preflight_warnings:string[];target_format:string;preset:string;frames_per_shot:number;fps:number;width:number;height:number;ltx_ready_at_plan_time:boolean;audio_available:boolean;approved_reference_ids:string[]}}|null }
type SavedStory = {id:string;title:string;story_text:string;film_plan?:Plan['film_plan']}
type ExportStatus={storyboard_id:string;revision:number;style_bible_revision:number;approved:boolean;total_shots:number;verified_shots:number;missing_shots:string[];all_verified:boolean;reconciled:boolean;manifest_ready:boolean;manifest_path:string|null;manifest:Plan['manifest'];remotion_ready:boolean;latest_render:RenderJob|null;source_batches:{id:string;created_at:string;verified_shots:number;total_shots:number}[];recommended_source_batch_id:string|null;ambiguous_source_batches:boolean;paused_batches:{id:string;status:string;queued_jobs:string[];completed_jobs:string[]}[]}
const approvedFable = `A frog searches for a crossing at a river. A scorpion asks the frog for a ride across. The frog fears being stung. The scorpion reasons that if he stung the frog, both would die in the river. The frog agrees, and they cross the river together. Halfway across, the scorpion stings the frog. The frog asks why. The scorpion answers that it is in his nature. Both face a tragic end.`

async function requestJson<T>(url:string, init?:RequestInit):Promise<T>{const response=await fetch(url,init);const data=await response.json();if(!response.ok)throw new Error(data.detail??'The local API rejected the request');return data as T}
const body=(value:unknown)=>({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)})

function CreativeReviewPanel({projectId,storyboardId,shot,references,onSaved}:{projectId:string;storyboardId:string;shot:Shot;references:Reference[];onSaved:()=>void}){
  const [continuity,setContinuity]=useState<{revision:number;approved_revision:number|null;document:{frog_reference_id:string;scorpion_reference_id:string;environment_reference_id:string|null;scenes:{title:string;continuity_notes:string;stage_layout:string;framing:string;river_width_scale:string;camera_orientation:string}[]}|null}|null>(null)
  const [checks,setChecks]=useState<Record<string,boolean>>({});const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  useEffect(()=>{let active=true;void requestJson<typeof continuity>(`/api/projects/${projectId}/scene-continuity`).then(value=>{if(active)setContinuity(value)}).catch(e=>{if(active)setError(e instanceof Error?e.message:String(e))});return()=>{active=false}},[projectId])
  const verified=shot.job?.status==='completed'&&shot.job.exit_code===0&&Boolean(shot.job.verification_metadata?.verified_output)&&Boolean(shot.job.result_path)&&shot.job.settings_match!==false
  if(!verified||!shot.job?.result_path)return null
  const document=continuity?.document;const selected=[document?.frog_reference_id,document?.scorpion_reference_id,document?.environment_reference_id].filter(Boolean) as string[]
  const labels=[['identities','The frog and scorpion match the approved original references'],['count','The number of visible characters matches the scene specification'],['environment','The river/environment has the specified width and scale'],['framing','The composition and camera orientation match the scene plan'],['artifacts','There are no duplicate characters or unintended creatures']]
  const scene=document?.scenes.find(item=>item.title.toLocaleLowerCase()===shot.scene_title.toLocaleLowerCase())
  const submit=async(next:'approved'|'rejected')=>{if(!continuity||continuity.approved_revision!==continuity.revision){setError('Approve the current project continuity package before recording a clip review.');return}if(next==='approved'&&!labels.every(([key])=>checks[key as string])){setError('Confirm every visual checklist item before approval.');return}if(next==='rejected'&&!reason.trim()){setError('Add a reason so the rejection can guide the next review.');return}setBusy(true);setError('');try{await requestJson(`/api/storyboards/${storyboardId}/shots/${shot.id}/creative-review`,body({decision:next,continuity_revision:continuity.revision,checklist:checks,reason}));onSaved()}catch(e){setError(e instanceof Error?e.message:String(e))}finally{setBusy(false)}}
  return <div className="creative-review"><div className="section-kicker">CREATIVE REVIEW · SEPARATE FROM FFPROBE</div><p>Technical status: verified. Compare the clip manually with the approved references; this app does not detect duplicate or incorrect characters.</p>
    <div className="creative-review-compare"><figure><video controls playsInline preload="metadata" src={`/api/media/file?path=${encodeURIComponent(shot.job.result_path)}`}/><figcaption>Generated clip · {shot.title}</figcaption></figure>{selected.map(id=>{const reference=references.find(item=>item.id===id);return reference?<figure key={id}><img src={`/api/projects/${projectId}/references/${id}/file`} alt={`Approved reference ${reference.name}`}/><figcaption>{reference.name} · approved project reference</figcaption></figure>:null})}</div>
    <p className="settings-intro">Scene layout: {scene?.stage_layout||'No stage layout saved'} · Framing: {scene?.framing||shot.framing||'Not specified'} · River scale: {scene?.river_width_scale||'Not specified'} · Camera: {scene?.camera_orientation||'Not specified'}</p>
    {shot.creative_review&&<div className={`film-style-notice ${shot.creative_review_current?'':'preflight-warning'}`}><Check size={14}/><span>Latest review: {shot.creative_review.decision}{shot.creative_review_current?' · current':' · stale for the current shot/continuity revision'} · {shot.creative_review.reason||'No rejection reason'} · {new Date(shot.creative_review.created_at).toLocaleString()}</span></div>}
    <div className="creative-review-checks">{labels.map(([key,label])=><label key={key}><input type="checkbox" checked={Boolean(checks[key])} onChange={event=>setChecks(current=>({...current,[key]:event.target.checked}))}/>{label}</label>)}</div>
    <label className="setting-field wide">Review notes / rejection reason<textarea maxLength={2000} value={reason} onChange={event=>setReason(event.target.value)} placeholder="Record what should change, such as duplicate frog, incorrect creature, narrow puddle, or framing issue."/></label>
    {error&&<div className="model-caution"><AlertTriangle size={13}/><span>{error}</span></div>}
    <div className="film-action-row"><button className="button secondary" disabled={busy} onClick={()=>void submit('rejected')}>{busy?'Saving…':'Reject clip with reason'}</button><button className="button primary" disabled={busy||!continuity||continuity.approved_revision!==continuity.revision||!labels.every(([key])=>checks[key as string])} onClick={()=>void submit('approved')}>{busy?'Saving…':'Approve creative review'}</button></div>
  </div>
}

function SingleSceneValidation({projectId,storyboardId,shot,currentStyleRevision,ltxReady,onQueued}:{projectId:string;storyboardId:string;shot:Shot;currentStyleRevision:number;ltxReady:boolean;onQueued:()=>void}){
  const [continuity,setContinuity]=useState<{revision:number;approved_revision:number|null;document:{scenes:{title:string;anchor_reference_ids:string[]}[]}|null}|null>(null)
  const [experimental,setExperimental]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  useEffect(()=>{let active=true;void requestJson<typeof continuity>(`/api/projects/${projectId}/scene-continuity`).then(value=>{if(active)setContinuity(value)}).catch(()=>{});return()=>{active=false}},[projectId])
  const scene=continuity?.document?.scenes.find(item=>item.title.toLocaleLowerCase()===shot.scene_title.toLocaleLowerCase())
  const alreadyCurrent=shot.status==='verified'&&shot.job?.settings_match!==false
  const queue=async()=>{if(!window.confirm(`Queue one LTX shot only: “${shot.title}” (${shot.preset}, about ${shot.estimated_seconds.toFixed(2)} seconds of footage). No other shots will be queued. Local generation uses substantial resources.`))return;setBusy(true);setError('');try{await requestJson(`/api/storyboards/${storyboardId}/shots/${shot.id}/generate`,body({continuity_revision:experimental?continuity?.revision:undefined,use_experimental_multi_anchor:experimental}));onQueued()}catch(e){setError(e instanceof Error?e.message:String(e))}finally{setBusy(false)}}
  return <div className="single-scene-validation"><div><b>Controlled one-shot validation</b><p>Queues only this scene’s shot; it never starts or resumes a film batch.</p></div>{experimental&&<label className="film-approval-check"><input type="checkbox" checked onChange={()=>setExperimental(false)}/>Use experimental multi-image temporal anchors</label>}{!experimental&&<label className="film-approval-check"><input type="checkbox" checked={false} onChange={e=>setExperimental(e.target.checked)} disabled={!scene?.anchor_reference_ids.length||continuity?.approved_revision!==continuity?.revision}/>Use experimental multi-image temporal anchors {scene?.anchor_reference_ids.length?`(${scene.anchor_reference_ids.length} guide images)`:'(no scene anchors approved)'}</label>}<small>Default is independent I2V. Multiple --image guides constrain frames over time; they are not a character identity lock.</small><button className="button secondary" disabled={busy||!ltxReady||alreadyCurrent||!shot.prompt_reviewed||shot.reviewed_style_revision!==currentStyleRevision} onClick={()=>void queue()}>{busy?'Queueing…':'Queue this shot only'}</button>{alreadyCurrent&&<small>Current verified shot is protected from duplicate generation.</small>}{error&&<div className="model-caution"><AlertTriangle size={13}/><span>{error}</span></div>}</div>
}

export default function FilmPlanPage({projectId,projectName,onMessage,onNavigate,focusExport=false}:{projectId:string|null;projectName:string;onMessage:(message:string)=>void;onNavigate?:(page:string)=>void;focusExport?:boolean}){
  const [references,setReferences]=useState<Reference[]>([]);const [savedStories,setSavedStories]=useState<SavedStory[]>([]);const [presets,setPresets]=useState<Preset[]>([]);const [plans,setPlans]=useState<SavedStory[]>([])
  const [frogId,setFrogId]=useState('');const [scorpionId,setScorpionId]=useState('');const [sourceId,setSourceId]=useState('');const [storyText,setStoryText]=useState('');const [title,setTitle]=useState('The Frog and the Scorpion — River Crossing');const [format,setFormat]=useState('9:16');const [preset,setPreset]=useState('Short');const [seed,setSeed]=useState('');const [plan,setPlan]=useState<Plan|null>(null);const [busy,setBusy]=useState('');const [error,setError]=useState('');const [dirty,setDirty]=useState(false);const [reviewed,setReviewed]=useState(false);const [batch,setBatch]=useState<FilmBatch|null>(null);const [batchHistory,setBatchHistory]=useState<FilmBatch[]>([]);const [retrySelection,setRetrySelection]=useState<string[]>([]);const [remotionReady,setRemotionReady]=useState(false);const [ltxReady,setLtxReady]=useState(false);const [styleConflict,setStyleConflict]=useState(false);const [exportStatus,setExportStatus]=useState<ExportStatus|null>(null);const [sourceBatchId,setSourceBatchId]=useState('');const finalVideo=useRef<HTMLVideoElement|null>(null);const exportSection=useRef<HTMLElement|null>(null)
  const refresh=useCallback(async()=>{if(!projectId){setReferences([]);setPlans([]);setSavedStories([]);setPlan(null);setBatch(null);setStyleConflict(false);return}try{const [r,s,p,i,bible]=await Promise.all([requestJson<Reference[]>(`/api/projects/${projectId}/references`),requestJson<SavedStory[]>(`/api/projects/${projectId}/storyboards`),requestJson<Preset[]>('/api/presets'),requestJson<{ltx:{ready:boolean};remotion:{ready:boolean}}>('/api/integrations'),requestJson<{fields:Record<string,string>}>(`/api/projects/${projectId}/style-bible`)]);setReferences(r);setSavedStories(s.filter(item=>item.story_text?.trim()));setPlans(s.filter(item=>Boolean(item.film_plan)));setPresets(p);setLtxReady(i.ltx.ready);setRemotionReady(i.remotion.ready);setStyleConflict(/do not use riverbank or water imagery/i.test(bible.fields.negative_constraints??''))}catch(e){setError(e instanceof Error?e.message:'Could not load project data')}},[projectId])
  useEffect(()=>{setPlan(null);setDirty(false);setReviewed(false);setFrogId('');setScorpionId('');setStoryText('');setSourceId('');void refresh()},[refresh])
  const refreshExport=useCallback(async(id:string)=>{const value=await requestJson<ExportStatus>(`/api/storyboards/${id}/film-plan/export-status`);setExportStatus(value);setRemotionReady(value.remotion_ready);setSourceBatchId(current=>value.source_batches.some(item=>item.id===current)?current:(value.recommended_source_batch_id??''));return value},[])
  useEffect(()=>{if(!plan?.film_plan){setExportStatus(null);return}let live=true;const load=async()=>{try{const value=await requestJson<ExportStatus>(`/api/storyboards/${plan.id}/film-plan/export-status`);if(live){setExportStatus(value);setRemotionReady(value.remotion_ready);setSourceBatchId(current=>value.source_batches.some(item=>item.id===current)?current:(value.recommended_source_batch_id??''))}}catch(e){if(live)setError(e instanceof Error?e.message:'Could not check export readiness')}};void load();const timer=window.setInterval(load,2500);return()=>{live=false;window.clearInterval(timer)}},[plan?.id,plan?.revision,plan?.style_bible_revision])
  useEffect(()=>{if(focusExport)exportSection.current?.scrollIntoView({behavior:'smooth',block:'start'})},[focusExport,plan?.id])
  const frog=references.find(item=>item.id===frogId);const scorpion=references.find(item=>item.id===scorpionId)
  async function loadPlan(id:string){setBusy('load');setError('');try{const data=await requestJson<Plan>(`/api/storyboards/${id}`);setPlan(data);setTitle(data.title);setStoryText(data.story_text);setPreset(data.film_plan?.metadata.preset??'Short');setFormat(data.film_plan?.metadata.target_format??'9:16');const ids=data.film_plan?.metadata.approved_reference_ids??[];setFrogId(ids[0]??'');setScorpionId(ids[1]??'');setDirty(false);setReviewed(false);const batches=await requestJson<FilmBatch[]>(`/api/storyboards/${id}/film-plan/batches`);const authoritative=batches.find(item=>['running','paused'].includes(item.status))??batches.find(item=>item.status==='completed'&&item.completed_shots===item.total_shots)??batches[0]??null;setBatch(authoritative);setBatchHistory(batches.filter(item=>item.id!==authoritative?.id));setRetrySelection([])}catch(e){setError(e instanceof Error?e.message:'Could not load saved film plan')}finally{setBusy('')}}
  async function build(){if(!projectId||!frogId||!scorpionId)return;setBusy('build');setError('');try{const data=await requestJson<Plan>(`/api/projects/${projectId}/film-plans`,body({story_text:storyText,title,frog_reference_id:frogId,scorpion_reference_id:scorpionId,target_format:format,preset,seed:seed===''?null:Number(seed)}));setPlan(data);setBatch(null);setRetrySelection([]);setDirty(false);setReviewed(false);await refresh();onMessage(`Saved a separate ${data.shots.length}-shot plan as storyboard revision ${data.revision}; no jobs were queued.`)}catch(e){setError(e instanceof Error?e.message:'Could not build film plan')}finally{setBusy('')}}
  function changeShot(index:number,key:keyof Shot,value:string){if(!plan)return;const shots=plan.shots.map((shot,i)=>i===index?({...shot,[key]:value,...(key==='dialogue'?{caption:value}:{}),prompt_reviewed:false,generation_payload:{...shot.generation_payload,...(key==='prompt'?{prompt:value,shot_prompt:value}:{}),...(key==='dialogue'?{caption:value}:{})}}):shot);setPlan({...plan,shots,film_plan:plan.film_plan?{...plan.film_plan,approved:false}:null});setDirty(true);setReviewed(false)}
  async function save(){if(!plan)return;setBusy('save');setError('');try{const data=await requestJson<Plan>(`/api/storyboards/${plan.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:plan.revision,title,story_text:plan.story_text,shots:plan.shots.map(({job,status,...shot})=>shot)})});setPlan(data);setStoryText(data.story_text);setDirty(false);setReviewed(false);await refresh();onMessage(`Film plan saved as revision ${data.revision}; prior approval is no longer current.`)}catch(e){setError(e instanceof Error?e.message:'Could not save plan')}finally{setBusy('')}}
  async function approve(){if(!plan)return;setBusy('approve');setError('');try{const data=await requestJson<Plan>(`/api/storyboards/${plan.id}/film-plan/approve`,body({revision:plan.revision,style_bible_revision:plan.style_bible_revision}));setPlan(data);setReviewed(false);await refresh();onMessage(`Approved the saved film plan revision ${data.revision}. No generation jobs were queued.`)}catch(e){setError(e instanceof Error?e.message:'Could not approve saved plan')}finally{setBusy('')}}
  const pollBatch=useCallback(async(id:string)=>{try{const data=await requestJson<FilmBatch>(`/api/film-batches/${id}`);setBatch(data);setRetrySelection(current=>current.filter(shotId=>data.shots.some(shot=>shot.shot_id===shotId&&['failed','cancelled'].includes(shot.status))));if(data.status==='completed'&&projectId){const currentPlan=await requestJson<Plan>(`/api/storyboards/${data.storyboard_id}`);setPlan(currentPlan)} }catch(e){setError(e instanceof Error?e.message:'Could not refresh film batch status')}},[projectId])
  useEffect(()=>{if(!batch?.id||!['running','paused'].includes(batch.status))return;const timer=window.setInterval(()=>void pollBatch(batch.id),1800);return()=>window.clearInterval(timer)},[batch?.id,batch?.status,pollBatch])
  async function generateFilm(){if(!plan)return;const missing=exportStatus?.missing_shots??plan.shots.map(shot=>shot.title);if(!window.confirm(`Queue only the ${missing.length} missing or stale shot(s)?\n\n${missing.join('\n')}\n\nExisting verified outputs will be preserved and reused. This starts local LTX GPU work.`))return;setBusy('generate');setError('');try{const data=await requestJson<FilmBatch>(`/api/storyboards/${plan.id}/film-plan/generate`,body({revision:plan.revision,style_bible_revision:plan.style_bible_revision}));if(data.status==='reconciliation_required'||data.status==='ready_for_export'){await refreshExport(plan.id);onMessage(data.message??'No new jobs were queued; continue to Export / Remotion.');onNavigate?.('Export / Remotion');return}setBatch(data);setRetrySelection([]);if(data.status==='completed')await pollBatch(data.id);onMessage(`Film batch queued: ${data.queued_shots} missing shot jobs will use the single local worker.`)}catch(e){setError(e instanceof Error?e.message:'Could not queue film batch')}finally{setBusy('')}}
  async function reconcileVerifiedShots(){if(!plan||!exportStatus||!sourceBatchId)return;const queued=exportStatus.paused_batches.reduce((count,item)=>count+item.queued_jobs.length,0);const completed=exportStatus.paused_batches.reduce((count,item)=>count+item.completed_jobs.length,0);if(!window.confirm(`Freshly ffprobe all ${exportStatus.total_shots} clips in the selected completed batch, make those job links current for this approved revision, and cancel ${queued} still-queued duplicate job(s)? ${completed} already completed extra output(s) will be preserved. This does not start LTX or Remotion.`))return;setBusy('reconcile');setError('');try{const response=await requestJson<{storyboard:Plan;cancelled_job_ids:string[];reconciled_shots:number;preserved_completed_outputs:number}>(`/api/storyboards/${plan.id}/film-plan/reconcile`,body({revision:plan.revision,style_bible_revision:plan.style_bible_revision,source_batch_id:sourceBatchId}));setPlan(response.storyboard);const batches=await requestJson<FilmBatch[]>(`/api/storyboards/${plan.id}/film-plan/batches`);setBatch(batches[0]??null);await refreshExport(plan.id);onMessage(`Reconciled ${response.reconciled_shots} shots, cancelled ${response.cancelled_job_ids.length} queued duplicates, and preserved ${response.preserved_completed_outputs} completed extra output(s). No generation ran.`)}catch(e){setError(e instanceof Error?e.message:'Could not reconcile verified shots')}finally{setBusy('')}}
  async function assembleVerifiedClips(){if(!plan)return;setBusy('assemble');setError('');try{const data=await requestJson<Plan>(`/api/storyboards/${plan.id}/manifest`,{method:'POST'});setPlan(data);await refreshExport(plan.id);onMessage(`Composition assembled from ${data.manifest?.shots?.length??0} existing verified clips. No render was started.`)}catch(e){setError(e instanceof Error?e.message:'Could not assemble verified clips')}finally{setBusy('')}}
  async function batchAction(action:'pause'|'resume'|'cancel'){if(!batch)return;if(action==='cancel'&&!window.confirm('Cancel all remaining queued shots? A running shot will be terminated and retained outputs will remain.'))return;setBusy(action);setError('');try{const data=await requestJson<FilmBatch>(`/api/film-batches/${batch.id}/${action}`,{method:'POST'});setBatch(data);onMessage(action==='pause'?'Batch paused; a running shot may finish, and no next shot will start.':action==='resume'?'Batch resumed on the single local worker.':'Remaining film jobs cancelled; completed clips were retained.')}catch(e){setError(e instanceof Error?e.message:`Could not ${action} film batch`)}finally{setBusy('')}}
  async function retryShots(){if(!batch||!retrySelection.length)return;setBusy('retry');setError('');try{const data=await requestJson<FilmBatch>(`/api/film-batches/${batch.id}/retry`,body({shot_ids:retrySelection}));setBatch(data);setRetrySelection([]);onMessage(`Queued ${retrySelection.length} selected failed or cancelled shot(s); completed shots were not duplicated.`)}catch(e){setError(e instanceof Error?e.message:'Could not retry selected shots')}finally{setBusy('')}}
  async function renderFilm(){if(!plan)return;const retry=exportStatus?.latest_render?.status==='failed';if(!window.confirm(`${retry?'Retry':'Render'} the verified ${plan.title} composition with local Remotion now? This starts a real render and may use substantial resources.`))return;setBusy('render');setError('');try{const job=await requestJson<{id:string}>(`/api/storyboards/${plan.id}/render`,{method:'POST'});await refreshExport(plan.id);onMessage(`Remotion render ${job.id} added to the local queue.`)}catch(e){setError(e instanceof Error?e.message:'Could not queue Remotion render')}finally{setBusy('')}}
  async function reveal(path:string){try{await requestJson('/api/outputs/reveal',body({path}));onMessage('Opened the verified output in Finder.')}catch(e){setError(e instanceof Error?e.message:'Could not reveal output')}}
  function selectSource(id:string){setSourceId(id);const selected=savedStories.find(item=>item.id===id);if(selected)setStoryText(selected.story_text)}
  const latestRender=exportStatus?.latest_render??null
  const renderActive=Boolean(latestRender&&['queued','running'].includes(latestRender.status))
  const verifiedFinal=Boolean(latestRender&&latestRender.status==='completed'&&latestRender.current&&latestRender.result_path&&plan?.manifest&&latestRender.verification_metadata?.verified_output&&latestRender.verification_metadata.verified_output.width===plan.manifest.width&&latestRender.verification_metadata.verified_output.height===plan.manifest.height&&latestRender.verification_metadata.verified_output.fps===plan.manifest.fps&&latestRender.verification_metadata.verified_output.frames===plan.manifest.duration_in_frames)
  return <section className="panel workspace-page film-plan-page">
    <div className="section-kicker">STORY-TO-FILM · LOCAL PRODUCTION</div><h2>{projectName||'Select a project'}</h2>
    {!projectId?<div className="empty-workspace"><Clapperboard size={18}/><b>Select a project first</b><span>Film plans, references and generation settings are project-scoped.</span></div>:<>
      <p className="settings-intro">Build a separate, editable production plan from an approved story. This deterministic planner handles the original Frog and Scorpion river-crossing fable; no planning model is configured. Building or approving a plan never queues generation.</p>
      <div className="settings-divider"/><div className="section-kicker">1 · STORY AND APPROVED REFERENCES</div>
      <div className="settings-form-grid">
        <label className="setting-field wide">Saved story text<select value={sourceId} onChange={event=>selectSource(event.target.value)}><option value="">Enter a new story below</option>{savedStories.map(item=><option value={item.id} key={item.id}>{item.title}</option>)}</select></label>
        <div className="setting-field wide"><button type="button" className="button secondary mini" onClick={()=>{setStoryText(approvedFable);setSourceId('')}}><BookOpen size={13}/> Load the approved river-crossing fable</button></div>
        <label className="setting-field wide">Story text<textarea maxLength={20000} value={storyText} onChange={event=>{setStoryText(event.target.value);setSourceId('')}} placeholder="Enter the original Frog and Scorpion river-crossing fable…"/></label>
        <label className="setting-field">Plan title<input maxLength={160} value={title} onChange={event=>{setTitle(event.target.value);if(plan){setDirty(true);setReviewed(false)}}}/></label>
        <label className="setting-field">Frog character reference<select value={frogId} onChange={event=>setFrogId(event.target.value)}><option value="">Select linked original frog…</option>{references.map(item=><option value={item.id} key={item.id}>{item.name}{item.available?'':' · missing file'}</option>)}</select></label>
        <label className="setting-field">Scorpion character reference<select value={scorpionId} onChange={event=>setScorpionId(event.target.value)}><option value="">Select linked original scorpion…</option>{references.map(item=><option value={item.id} key={item.id}>{item.name}{item.available?'':' · missing file'}</option>)}</select></label>
        <label className="setting-field">Target film format<select value={format} onChange={event=>setFormat(event.target.value)}>{['9:16','16:9','1:1','4:3','3:2'].map(value=><option key={value}>{value}</option>)}</select></label>
        <label className="setting-field">LTX duration per shot<select value={preset} onChange={event=>{const choice=presets.find(item=>item.name===event.target.value);if(choice?.visual_drift_warning&&!window.confirm('Experimental 193-frame shots may show visual drift and use substantial resources. Continue?'))return;setPreset(event.target.value)}}>{presets.map(item=><option key={item.name} value={item.name}>{item.name} · {item.frames} frames · {item.duration.toFixed(2)}s</option>)}</select></label>
        <label className="setting-field">Seed (optional)<input type="number" min="0" max="4294967295" value={seed} onChange={event=>setSeed(event.target.value)}/></label>
      </div>
      {frog&&scorpion&&frogId===scorpionId&&<div className="model-caution"><AlertTriangle size={13}/> Choose two distinct linked character references.</div>}
      <div className="film-reference-grid">{([['frog',frog],['scorpion',scorpion]] as const).map(([kind,item])=><article className="film-reference-card" key={kind}><div className="section-kicker">{kind.toUpperCase()} · PROJECT LINK</div>{item?<>{item.available?<img src={`/api/projects/${projectId}/references/${item.id}/file`} alt={`${item.name} linked character reference`}/>:<div className="missing-reference"><AlertTriangle size={16}/><b>Reference file is unavailable</b><span>Restore it at the linked path or choose a re-linked original. Then use Recheck project data.</span></div>}<b>{item.name}</b><code>{item.path}</code><small>{item.mime_type} · {item.size_bytes.toLocaleString()} bytes</small></>:<div className="empty-workspace"><AlertTriangle size={16}/><b>No reference selected</b><span>Link an approved character image under References, then select it here.</span></div>}</article>)}</div>
      {styleConflict&&<div className="film-style-notice"><BookOpen size={14}/><span>The current style bible prohibits river and water imagery required by this story. Building the plan will revise only that conflict, retain the prior bible revision in local history, and continue to exclude old riverbank, video, benchmark, and storyboard media.</span></div>}
      <div className="film-action-row"><button className="button primary" disabled={busy!==''||!storyText.trim()||!frog?.available||!scorpion?.available||frogId===scorpionId} onClick={()=>void build()}>{busy==='build'?<LoaderCircle className="spin" size={14}/>:<Sparkles size={14}/>} {plan?'Build New Film Plan':'Build Film Plan'}</button><button className="button secondary" disabled={busy!==''} onClick={()=>void refresh()}><RefreshCw size={13}/> Recheck project data</button></div>
      {plans.length>0&&<label className="setting-field saved-film-select">Open a saved film plan<select value={plan?.id??''} onChange={event=>event.target.value?void loadPlan(event.target.value):setPlan(null)}><option value="">Choose a saved plan…</option>{plans.map(item=><option key={item.id} value={item.id}>{item.title} · {item.story_text?.slice(0,72)}</option>)}</select></label>}
      {error&&<div className="model-caution"><AlertTriangle size={13}/><span>{error}</span></div>}
      {plan&&plan.film_plan&&<>
        <div className="settings-divider"/><div className="film-plan-header"><div><div className="section-kicker">SAVED PLAN · REVISION {plan.revision}</div><h3>{plan.title}</h3><p>{plan.film_plan.metadata.planner_disclosure}</p></div><span className={`job-status ${plan.film_plan.approved?'completed':'planned'}`}>{plan.film_plan.approved?'Approved revision':'Review required'}</span></div>
        <div className="film-plan-summary"><div><span>SCENES</span><b>{plan.film_plan.metadata.scenes.length}</b></div><div><span>SHOTS</span><b>{plan.film_plan.metadata.shot_count}</b></div><div><span>ESTIMATED SOURCE</span><b>{plan.film_plan.metadata.estimated_seconds.toFixed(2)}s</b></div><div><span>FORMAT</span><b>{plan.film_plan.metadata.width}×{plan.film_plan.metadata.height} · {plan.film_plan.metadata.fps}fps</b></div><div><span>WORKLOAD</span><b>{plan.film_plan.metadata.expected_workload}</b></div><div><span>LTX AT PLAN</span><b>{plan.film_plan.metadata.ltx_ready_at_plan_time?'Detected':'Unavailable'}</b></div></div>
        <div className="film-export-ribbon" aria-label="Persistent film export status"><div><b>{exportStatus?.verified_shots??0}/{exportStatus?.total_shots??plan.shots.length}</b><span>source clips verified</span></div><div><b>{exportStatus?.manifest_ready?'Composition ready':'Composition not prepared'}</b><span>{exportStatus?.manifest_ready&&exportStatus.manifest?`${exportStatus.manifest.duration_in_frames} frames · ${(exportStatus.manifest.duration_in_frames/exportStatus.manifest.fps).toFixed(2)}s · ${exportStatus.manifest.width}×${exportStatus.manifest.height} · ${exportStatus.manifest.fps} fps`:'Manifest preparation is metadata-only'}</span></div><div><b>{verifiedFinal?'Final film rendered':renderActive?`Rendering ${latestRender?.progress??0}%`:'Final export pending'}</b><span>{verifiedFinal?'Verified MP4 ready':renderActive?'Render status is saved and refresh-safe':'No final video will be claimed before Remotion completes'}</span></div></div>
        <div className="model-caution"><AlertTriangle size={13}/><span>{plan.film_plan.metadata.reference_limit_note} The final audio capability is unavailable; no audio will be fabricated.</span></div>
        {plan.film_plan.metadata.experimental_drift_warning&&<div className="model-caution preflight-warning"><AlertTriangle size={13}/><span>Experimental 193-frame shots are behind an explicit warning and may show visual drift over this film's longer generation duration.</span></div>}
        {plan.film_plan.metadata.style_bible_notice&&<div className="film-style-notice"><BookOpen size={14}/><span>{plan.film_plan.metadata.style_bible_notice}</span></div>}
        {plan.film_plan.metadata.preflight_warnings.length>0&&<div className="model-caution preflight-warning"><AlertTriangle size={13}/><span>{plan.film_plan.metadata.preflight_warnings.join(' ')}</span></div>}
        {plan.film_plan.metadata.scenes.map((scene,sceneIndex)=>{const shots=plan.shots.filter(shot=>shot.scene_title===scene.title);return <section className="film-scene-card" key={scene.title}><div className="film-scene-heading"><span>{String(sceneIndex+1).padStart(2,'0')}</span><div><h4>{scene.title}</h4><p>{scene.visual_description}</p></div><small>~{scene.estimated_seconds.toFixed(2)}s · {scene.transition_after} out</small></div>{shots.map(shot=>{const absoluteIndex=plan.shots.findIndex(item=>item.id===shot.id);const reference=references.find(item=>item.id===shot.reference_ids[0]);return <article className="film-shot-card" key={shot.id}><div className="film-shot-top"><b>{absoluteIndex+1}. {shot.title}</b><span>{shot.framing} · {shot.estimated_seconds.toFixed(2)}s · {shot.preset} · {shot.width}×{shot.height}@{shot.fps}</span></div><div className="film-shot-data"><p><strong>Action:</strong> {shot.visual_description}</p><p><strong>Characters:</strong> {shot.characters.join(', ')||'None listed'} · <strong>One attached reference:</strong> {reference?.name??'Missing link'}</p><label className="setting-field wide">Shot prompt<textarea maxLength={4000} value={shot.prompt} onChange={event=>changeShot(absoluteIndex,'prompt',event.target.value)}/></label><label className="setting-field wide">Dialogue / caption<textarea maxLength={1000} value={shot.dialogue} onChange={event=>changeShot(absoluteIndex,'dialogue',event.target.value)}/></label><small>Transition after: {shot.transition_after} · Output: {shot.output_location}</small>{shot.job&&<small className="job-status">Existing job: {shot.job.status}{shot.job.result_path?` · ${shot.job.result_path}`:''}{shot.job.error?` · ${shot.job.error}`:''}</small>}</div></article>})}</section>})}
        <div className="single-scene-validation-list">{plan.shots.map(shot=><SingleSceneValidation key={shot.id} projectId={projectId!} storyboardId={plan.id} shot={shot} currentStyleRevision={plan.style_bible_revision} ltxReady={ltxReady} onQueued={()=>void loadPlan(plan.id)}/>)}</div>
        {plan.shots.filter(shot=>shot.job?.verification_metadata?.verified_output&&shot.job.result_path).map(shot=><CreativeReviewPanel key={`${shot.id}-${shot.job?.id}`} projectId={projectId!} storyboardId={plan.id} shot={shot} references={references} onSaved={()=>void loadPlan(plan.id)}/>)}
        <div className="film-action-row"><button className="button secondary" disabled={!dirty||busy!==''} onClick={()=>void save()}><Save size={13}/> Save plan edits</button><label className="film-approval-check"><input type="checkbox" checked={reviewed} onChange={event=>setReviewed(event.target.checked)}/> I reviewed every scene, shot prompt, timing estimate, and the one-image references above.</label><button className="button primary" disabled={busy!==''||dirty||!reviewed||plan.film_plan.approved} onClick={()=>void approve()}>{busy==='approve'?<LoaderCircle className="spin" size={14}/>:<Check size={14}/>} Approve Film Plan</button></div>
        <p className="settings-intro">Approval records exactly revision {plan.revision} and style-bible revision {plan.style_bible_revision}. Editing the plan or style bible requires saving and reviewing again. Approval does not queue LTX work.</p>
        {plan.film_plan.approved&&<section className="film-batch-panel"><div className="section-kicker">3 · CONTROLLED LOCAL GENERATION</div><h3>Generate missing shots only</h3><p className="settings-intro">The local worker runs one LTX job at a time. Existing current verified clips are reused. Queueing missing shots requires a confirmation that lists the exact shots.</p>{exportStatus?.source_batches.length? <div className="film-style-notice"><Check size={14}/><span>A complete verified source batch already exists. Reconcile its 12 existing clips and continue to Export / Remotion. Generate Film is blocked from creating duplicates.</span></div>:null}{exportStatus?.paused_batches.some(item=>item.queued_jobs.length>0)&&<div className="model-caution preflight-warning"><AlertTriangle size={13}/><span>The paused batch still has {exportStatus.paused_batches.reduce((n,item)=>n+item.queued_jobs.length,0)} queued job(s). Reconcile or cancel that queue before generating any missing shots.</span></div>}{!ltxReady&&<div className="model-caution"><AlertTriangle size={13}/> LTX is currently unavailable. Export of existing clips does not require LTX.</div>}<div className="film-action-row">{exportStatus?.all_verified||exportStatus?.source_batches.length?<button className="button secondary" disabled={busy!==''} onClick={()=>onNavigate?.('Export / Remotion')}><Clapperboard size={14}/> All clips ready — go to Export / Remotion</button>:<button className="button primary" disabled={busy!==''||!ltxReady||!exportStatus||Boolean(batch&&['running','paused'].includes(batch.status))||Boolean(exportStatus.paused_batches.some(item=>item.queued_jobs.length>0))} onClick={()=>void generateFilm()}>{busy==='generate'?<LoaderCircle className="spin" size={14}/>:<Clapperboard size={14}/>} Generate Missing Shots</button>}{batch?.status==='running'&&<button className="button secondary" disabled={busy!==''} onClick={()=>void batchAction('pause')}>Pause after current shot</button>}{batch?.status==='paused'&&<button className="button secondary" disabled={busy!==''} onClick={()=>void batchAction('resume')}>Resume batch</button>}{batch&&['running','paused'].includes(batch.status)&&<button className="button secondary" disabled={busy!==''} onClick={()=>void batchAction('cancel')}>Cancel remaining shots</button>}<button className="button secondary" disabled={!batch||busy!==''} onClick={()=>batch&&void pollBatch(batch.id)}><RefreshCw size={12}/> Refresh status</button></div>
          {batch&&<><div className="batch-progress-heading"><b>Current approved production · {batch.status}</b><span>{batch.completed_shots}/{batch.total_shots} verified · {batch.progress}%</span></div><div className="batch-progress"><span style={{width:`${batch.progress}%`}}/></div>{batch.resource_warnings?.map(warning=><div className="model-caution preflight-warning" key={warning}><AlertTriangle size={13}/>{warning}</div>)}
            <div className="film-batch-shots">{batch.shots.map((item,index)=>{const job=item.job;const verified=job?.status==='completed'&&Boolean(job.verification_metadata?.verified_output);const canRetry=['failed','cancelled'].includes(item.status);return <article className="film-batch-shot" key={item.shot_id}><div className="film-batch-shot-head"><span>{String(index+1).padStart(2,'0')}</span><div><b>{item.scene_title} / {item.title}</b><small>{job?.payload?.job_label??item.skip_reason??'Waiting for job'}</small></div><span className={`job-status ${verified?'completed':item.status}`}>{verified?'verified':item.status}{item.status==='running'?` · ${item.progress}%`:''}</span>{canRetry&&<label className="retry-shot"><input type="checkbox" checked={retrySelection.includes(item.shot_id)} onChange={event=>setRetrySelection(current=>event.target.checked?[...current,item.shot_id]:current.filter(id=>id!==item.shot_id))}/> Retry</label>}</div>{job?.error&&<div className="model-caution">{job.error}</div>}{job?.events&&<details className="film-job-logs"><summary>Generation logs ({job.events.length})</summary>{job.events.map(event=><p key={event.id}><time>{new Date(event.time).toLocaleTimeString()}</time> <b>{event.level}</b> {event.message}</p>)}</details>}{verified&&job?.result_path&&<><video className="film-clip-preview" controls playsInline preload="metadata" src={`/api/media/file?path=${encodeURIComponent(job.result_path)}`}/><small>ffprobe verified {job.verification_metadata?.verified_output?.width}×{job.verification_metadata?.verified_output?.height} · {job.verification_metadata?.verified_output?.fps} fps · {job.verification_metadata?.verified_output?.frames} frames</small><button className="text-button" onClick={()=>void reveal(job.result_path!)}>Reveal clip in Finder</button></>}</article>})}</div>
            {retrySelection.length>0&&<button className="button secondary" disabled={busy!==''} onClick={()=>void retryShots()}>{busy==='retry'?<LoaderCircle className="spin" size={13}/>:<RefreshCw size={13}/>} Retry selected {retrySelection.length} failed/cancelled shots</button>}
          </>}
          {batchHistory.length>0&&<details className="film-history-disclosure"><summary>Previous production attempts ({batchHistory.length}) · outputs and logs retained</summary>{batchHistory.map(previous=><article className="film-history-batch" key={previous.id}><b>{previous.status==='cancelled'?'Previous attempt — cancelled duplicate queue; original clips preserved':`Previous batch · ${previous.status}`} · {previous.completed_shots}/{previous.total_shots} verified · {previous.id.slice(0,8)}</b>{previous.shots.map(item=><div className="film-history-shot" key={`${previous.id}-${item.shot_id}`}><span>{item.scene_title} / {item.title} · {item.status}</span>{item.job?.result_path&&<small>{item.job.result_path}</small>}{item.job?.error&&<small>{item.job.error}</small>}{item.job?.events&&<details className="film-job-logs"><summary>Logs ({item.job.events.length})</summary>{item.job.events.map(event=><p key={event.id}><time>{new Date(event.time).toLocaleTimeString()}</time> <b>{event.level}</b> {event.message}</p>)}</details>}</div>)}</article>)}</details>}
        </section>}
      </>}
      <section className="film-render-panel" ref={exportSection} aria-labelledby="film-export-title">
        <div className="settings-divider"/><div className="section-kicker">4 · EXPORT / REMOTION</div><h3 id="film-export-title">Prepare and export your film</h3>
        {!plan?.film_plan?<p className="settings-intro">Open a saved film plan or build one first. Remotion export becomes available here when an approved plan has current verified shot clips.</p>:<>
          <p className="settings-intro">Prepare writes a manifest from verified clip metadata; it does not encode a video. Render is a separate Remotion operation and always asks for confirmation. Export never queues or regenerates LTX shots.</p>
          {exportStatus?<div className="film-plan-summary"><div><span>SOURCE CLIPS</span><b>{exportStatus.verified_shots}/{exportStatus.total_shots} verified</b></div><div><span>APPROVED REVISION</span><b>{exportStatus.approved?`${exportStatus.revision} · current`:'Review required'}</b></div><div><span>COMPOSITION</span><b>{exportStatus.manifest_ready?'Ready':exportStatus.reconciled?'Needs preparation':'Needs reconciliation'}</b></div><div><span>REMOTION</span><b>{exportStatus.remotion_ready?'Detected':'Unavailable'}</b></div></div>:<p className="settings-intro">Checking saved export readiness…</p>}
          {exportStatus?.missing_shots.length? <div className="model-caution preflight-warning"><AlertTriangle size={13}/><span>Missing or stale: {exportStatus.missing_shots.join(', ')}. Export waits for these shots; it will not regenerate them automatically.</span></div>:null}
          {exportStatus?.manifest_ready&&exportStatus.manifest&&<div className="film-style-notice"><Check size={14}/><span>Composition ready · {exportStatus.manifest.duration_in_frames} frames = {(exportStatus.manifest.duration_in_frames/exportStatus.manifest.fps).toFixed(2)}s · {exportStatus.manifest.width}×{exportStatus.manifest.height} · {exportStatus.manifest.fps} fps.</span></div>}
          {verifiedFinal&&<video ref={finalVideo} className="film-clip-preview final-film-preview" controls playsInline preload="metadata" src={`/api/media/file?path=${encodeURIComponent(latestRender!.result_path!)}`}/>}
          {latestRender?.status==='failed'&&<div className="model-caution preflight-warning">Remotion render failed: {latestRender.error??'No error details were saved.'}</div>}
          {latestRender?.status==='completed'&&!verifiedFinal&&<div className="model-caution preflight-warning">A prior render is saved, but it does not match this current composition or lacks verified output metadata. It remains in history and is not presented as the current final film.</div>}
          {latestRender?.elapsed_seconds!=null&&latestRender.status==='completed'&&<p className="settings-intro">Completed render duration: {latestRender.elapsed_seconds.toFixed(1)} seconds.</p>}
          {latestRender?.status==='running'&&<div className="batch-progress-heading"><b>Remotion is rendering this composition</b><span>{latestRender.progress}%</span></div>}
          {renderActive&&<div className="batch-progress" role="progressbar" aria-label="Remotion render progress" aria-valuemin={0} aria-valuemax={100} aria-valuenow={latestRender?.progress??0}><span style={{width:`${latestRender?.progress??0}%`}}/></div>}
          {!verifiedFinal&&<div className="film-action-row">
            {!exportStatus?.manifest_ready&&<button className="button primary render-button" disabled={busy!==''||!exportStatus?.all_verified||!exportStatus.reconciled||!exportStatus.approved} onClick={()=>void assembleVerifiedClips()}>{busy==='assemble'?<LoaderCircle className="spin" size={13}/>:<Clapperboard size={13}/>} {busy==='assemble'?'Preparing composition…':'Prepare composition'}</button>}
            {exportStatus?.manifest_ready&&!renderActive&&<button className="button primary render-button" disabled={busy!==''||!remotionReady||!exportStatus.approved||!latestRender?.current&&latestRender?.status==='running'} onClick={()=>void renderFilm()}>{busy==='render'?<LoaderCircle className="spin" size={13}/>:<Clapperboard size={13}/>} {latestRender?.status==='failed'?'Retry render (confirmation required)':'Render final film (confirmation required)'}</button>}
            {renderActive&&<button className="button primary render-button" disabled aria-live="polite"><LoaderCircle className="spin" size={13}/> Rendering {latestRender?.progress??0}% · please wait</button>}
          </div>}
          {verifiedFinal&&<button className="button primary render-button" onClick={()=>void reveal(latestRender!.result_path!)}><Film size={13}/> Watch / Reveal final MP4</button>}
          {!exportStatus?.manifest_ready&&<p className="settings-intro">{exportStatus?.all_verified&&exportStatus.reconciled?'The next step prepares the composition manifest only.':'Waiting for every shot to be approved, reconciled, and verified before preparation.'}</p>}
          {!remotionReady&&<p className="settings-intro">Remotion is not detected. Recheck its local installation in Settings; verified clips remain preserved.</p>}
          {(exportStatus?.source_batches.length||exportStatus?.paused_batches.length||batchHistory.length>0)&&<details className="film-history-disclosure technical-export-controls"><summary>Technical recovery and batch history</summary>
            {exportStatus?.source_batches.length? <div className="film-style-notice"><Check size={14}/><span>{exportStatus.source_batches.length===1?'One complete verified source batch is available.':'Multiple complete source batches require an explicit choice.'} Reconciliation re-probes every clip before updating links.</span></div>:null}
            {exportStatus?.ambiguous_source_batches&&<label className="setting-field wide">Choose verified source batch<select value={sourceBatchId} onChange={event=>setSourceBatchId(event.target.value)}><option value="">Select source batch…</option>{exportStatus.source_batches.map(item=><option key={item.id} value={item.id}>{item.id} · {item.verified_shots}/{item.total_shots} verified · {new Date(item.created_at).toLocaleString()}</option>)}</select></label>}
            {!exportStatus?.reconciled&&<button className="button secondary" disabled={busy!==''||!exportStatus?.source_batches.length||!sourceBatchId||!exportStatus.approved} onClick={()=>void reconcileVerifiedShots()}>{busy==='reconcile'?<LoaderCircle className="spin" size={13}/>:<RefreshCw size={13}/>} Reconcile Verified Shots</button>}
            {exportStatus?.paused_batches.map(item=><p className="settings-intro" key={item.id}>Paused batch {item.id.slice(0,8)} · {item.queued_jobs.length} queued · {item.completed_jobs.length} completed. Reconciliation cancels only matching queued duplicates and keeps completed outputs.</p>)}
          </details>}
        </>}
      </section>
    </>}
  </section>
}
